from pybricks.hubs import PrimeHub
from pybricks.parameters import Direction, Port, Stop
from pybricks.pupdevices import Motor
from pybricks.robotics import DriveBase
from pybricks.tools import wait

# Set up all devices.
prime_hub = PrimeHub()
DRIVE_LEFT = Motor(Port.C, Direction.COUNTERCLOCKWISE)
DRIVE_RIGHT = Motor(Port.D, Direction.CLOCKWISE)
DRIVE_BASE = DriveBase(DRIVE_LEFT, DRIVE_RIGHT, 62.5, 79)

# Initialize variables.
SPEED = 950
ACCELERATION = 1300
TURN_SPEED = 200
TURN_ACCELERATION = 400
MANUAL_MOTOR_SPEED = 250
TELEOP_SPEED = 300
TELEOP_ACCEL = 1000
TELEOP_TURN = 200
TELEOP_TURN_ACCEL = 1000
TELEOP_ATTACH_SPEED = 600

def Accurate_Straight():
    DRIVE_BASE.straight(-40)
    DRIVE_BASE.use_gyro(True)
    DRIVE_BASE.reset(0, 0)
    DRIVE_BASE.settings(straight_speed=950)
    DRIVE_BASE.settings(straight_acceleration=1300)
    DRIVE_BASE.straight(250)

def my_4_90_s():
    DRIVE_BASE.use_gyro(True)
    DRIVE_BASE.settings(turn_rate=200)
    DRIVE_BASE.settings(turn_acceleration=400)
    DRIVE_BASE.reset(0, 0)
    DRIVE_BASE.turn(90)
    DRIVE_BASE.turn(90)
    DRIVE_BASE.turn(90)
    DRIVE_BASE.turn(90)

def Fast_Straight():
    DRIVE_BASE.straight(-40)
    DRIVE_BASE.use_gyro(True)
    DRIVE_BASE.reset(0, 0)
    DRIVE_BASE.settings(straight_speed=950)
    DRIVE_BASE.settings(straight_acceleration=2000)
    DRIVE_BASE.straight(250)
    DRIVE_BASE.straight(-250)

def Square():
    DRIVE_BASE.use_gyro(True)
    DRIVE_BASE.settings(turn_rate=200)
    DRIVE_BASE.settings(turn_acceleration=400)
    DRIVE_BASE.reset(0, 0)
    DRIVE_BASE.straight(250)
    DRIVE_BASE.turn(90)
    DRIVE_BASE.straight(250)
    DRIVE_BASE.turn(90)
    DRIVE_BASE.straight(250)
    DRIVE_BASE.turn(90)
    DRIVE_BASE.straight(250)
    DRIVE_BASE.turn(90)

def Fastest():
    DRIVE_BASE.settings(straight_speed=1050)
    DRIVE_BASE.settings(straight_acceleration=10000)
    DRIVE_BASE.straight(1200)
    wait(1000)
    DRIVE_BASE.straight(-1200)

def Gyro():
    DRIVE_BASE.use_gyro(False)
    DRIVE_BASE.settings(straight_speed=500)
    DRIVE_BASE.settings(straight_acceleration=900)
    DRIVE_BASE.use_gyro(True)
    DRIVE_BASE.straight(1000, then=Stop.BRAKE)
    wait(700)
    DRIVE_BASE.straight(-1000)


# The main program starts here.
Gyro()
